<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit(1);
foreach(['database','auth','owners','patients','attention','consultations','sanitary-events','sync']as$file)require __DIR__.'/../server/'.$file.'.php';
function assertSync(bool $value):void{if(!$value)throw new RuntimeException('ASSERTION_FAILED');}
try{
 $db=\VetCare\centralDatabase();foreach(['001_auth','002_owners','003_patients','004_consultations','005_sanitary_events']as$migration){$sql=file_get_contents(__DIR__.'/../database/mariadb/'.$migration.'.sql');$sql=str_replace('CREATE TABLE IF NOT EXISTS','CREATE TEMPORARY TABLE',$sql);$sql=preg_replace('/^\s*FOREIGN KEY[^\r\n]*\r?\n/m','',$sql);$sql=preg_replace('/,\s*\)/',"\n)",$sql);foreach(explode(';',$sql)as$statement)if(trim($statement)!=='')$db->exec($statement);}
 $actor=\VetCare\createUser($db,['username'=>'sync-vet','name'=>'Prueba temporal','role'=>'veterinario','password'=>'clave-temporal-de-prueba']);$ownerId=\VetCare\uuid();$patientId=\VetCare\uuid();$consultationId=\VetCare\uuid();
 $owner=['action'=>'createOwner','entityId'=>$ownerId,'input'=>['operationId'=>\VetCare\uuid(),'name'=>'Propietario offline','phone'=>'','address'=>'','locality'=>'']];$patient=['action'=>'createPatient','entityId'=>$patientId,'input'=>['operationId'=>\VetCare\uuid(),'ownerId'=>$ownerId,'name'=>'Paciente offline','species'=>'Perro','breed'=>'','birthDate'=>null,'ageValue'=>null,'ageUnit'=>null,'ageReference'=>null]];$consultation=['action'=>'createConsultation','entityId'=>$consultationId,'input'=>['operationId'=>\VetCare\uuid(),'kind'=>'consulta','patientId'=>$patientId,'patientVersion'=>1,'date'=>'2026-01-01','reason'=>'Consulta offline','treatment'=>'','notes'=>'','weight'=>'','temperature'=>'','heartRate'=>'','respiratoryRate'=>'']];
 $result=\VetCare\syncPush($db,$actor,['operations'=>[$owner,$patient,$consultation]]);assertSync(count($result['results'])===3);foreach($result['results']as$entry)assertSync($entry['status']==='applied');assertSync($result['results'][0]['entity']['id']===$ownerId&&$result['results'][1]['entity']['id']===$patientId&&$result['results'][2]['entity']['id']===$consultationId);assertSync((int)$db->query('SELECT COUNT(*) FROM vc_owners')->fetchColumn()===1&&(int)$db->query('SELECT COUNT(*) FROM vc_patients')->fetchColumn()===1&&(int)$db->query('SELECT COUNT(*) FROM vc_consultations')->fetchColumn()===1);
 $retry=\VetCare\syncPush($db,$actor,['operations'=>[$owner,$patient,$consultation]]);assertSync(array_column($retry['results'],'status')===['applied','applied','applied']);assertSync((int)$db->query('SELECT COUNT(*) FROM vc_consultations')->fetchColumn()===1);
 $updated=\VetCare\syncPush($db,$actor,['operations'=>[['action'=>'updateOwner','entityId'=>$ownerId,'input'=>['operationId'=>\VetCare\uuid(),'id'=>$ownerId,'version'=>1,'name'=>'Propietario actualizado','phone'=>'','address'=>'','locality'=>'','active'=>true]]]]);assertSync($updated['results'][0]['entity']['version']===2);
 $bad=\VetCare\syncPush($db,$actor,['operations'=>[['action'=>'createPatient','entityId'=>\VetCare\uuid(),'input'=>['operationId'=>\VetCare\uuid(),'ownerId'=>\VetCare\uuid(),'name'=>'Sin dueño','species'=>'Gato','breed'=>'','birthDate'=>null,'ageValue'=>null,'ageUnit'=>null,'ageReference'=>null]]]]);assertSync($bad['results'][0]['status']==='blocked'&&$bad['results'][0]['code']==='PATIENT_OWNER_REQUIRED');
 echo "MariaDB: sincronización de propietarios, pacientes y consultas, UUID offline, reintentos y bloqueo comprobados en tablas temporales.\n";
}catch(Throwable){fwrite(STDERR,"No se completó la prueba real de sincronización. Revisa db:check y permisos de tablas temporales.\n");exit(1);}
